"""Writes demo.m3u from tools/catalog.py. Run: python3 tools/build_playlist.py"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from catalog import CHANNELS, FILMS, PAGES, SERIES  # noqa: E402

ROOT = Path(__file__).resolve().parent.parent

lines = [
    "#EXTM3U",
    "# Kinelia legal demo playlist - Creative Commons works and public test streams only.",
    f"# Credits and licenses: {PAGES}/",
    "# TV guide (invented programmes): guide-en.xml.gz, guide-fr.xml.gz, guide-es.xml.gz",
    "# Generated by tools/build_playlist.py - edit tools/catalog.py, not this file.",
    "# Every line below must be tested before each Google Play review (see README).",
    "",
    "# ---------- Movies ----------",
]
for f in FILMS:
    lines.append(f'#EXTINF:-1 tvg-logo="{PAGES}/posters/{f["slug"]}.jpg?v=2" group-title="{f["group"]}",{f["title"]} ({f["year"]})')
    lines.append(f["url"])
lines += ["", '# ---------- Series (episodes recognized by "S01E01" in the title) ----------']
for s in SERIES:
    lines.append(f'#EXTINF:-1 tvg-logo="{PAGES}/posters/caminandes.jpg?v=2" group-title="Kids & Family",{s["title"]}')
    lines.append(s["url"])
lines += ["", "# ---------- Live TV (public test streams, invented channel names) ----------"]
for c in CHANNELS:
    lines.append(f'#EXTINF:-1 tvg-id="{c["id"]}" tvg-logo="{PAGES}/posters/{c["logo"]}.png?v=2" group-title="{c["group"]}",{c["name"]}')
    lines.append(c["url"])

(ROOT / "demo.m3u").write_text("\n".join(lines) + "\n", encoding="utf-8")
print("demo.m3u:", sum(1 for l in lines if l.startswith("#EXTINF")), "entries")
